import pytest
from grades import letter_grade, final_score


def test_letter_grade_max():
    assert letter_grade(100) == "A"


def test_letter_grade_a_threshold():
    assert letter_grade(90) == "A"


def test_letter_grade_b_upper():
    assert letter_grade(89) == "B"


def test_letter_grade_b_threshold():
    assert letter_grade(80) == "B"


def test_letter_grade_c_upper():
    assert letter_grade(79) == "C"


def test_letter_grade_c_threshold():
    assert letter_grade(70) == "C"


def test_letter_grade_d_upper():
    assert letter_grade(69) == "D"


def test_letter_grade_d_threshold():
    assert letter_grade(60) == "D"


def test_letter_grade_f_upper():
    assert letter_grade(59) == "F"


def test_letter_grade_zero():
    assert letter_grade(0) == "F"


def test_letter_grade_negative_raises():
    with pytest.raises(ValueError):
        letter_grade(-1)


def test_letter_grade_over_100_raises():
    with pytest.raises(ValueError):
        letter_grade(101)


def test_final_score_empty():
    assert final_score([]) is None


def test_final_score_single():
    assert final_score([85]) == 85


def test_final_score_round_half_to_even_down():
    assert final_score([88, 89]) == 88


def test_final_score_round_half_to_even_up():
    assert final_score([89, 90]) == 90


def test_final_score_round_half_to_even_86_point_5():
    assert final_score([86, 87]) == 86


def test_final_score_round_nearest():
    assert final_score([88, 89, 89]) == 89


def test_final_score_negative_raises():
    with pytest.raises(ValueError):
        final_score([90, -1])


def test_final_score_over_100_raises():
    with pytest.raises(ValueError):
        final_score([101, 80])
